var documenterSearchIndex = {"docs":
[{"category":"section","location":"#MX2RKKY","page":"Home","text":"MX2RKKY is a Julia implementation of the Monte Carlo algorithm used to study magnetic order in an XY-model on a triangular lattice with a long-range chiral interaction between local magnetic moments.\n\nDocumentation for MX2RKKY.","title":"MX2RKKY"},{"category":"section","location":"#MX2RKKY.lattice","page":"Home","text":"","title":"MX2RKKY.lattice"},{"category":"section","location":"#MX2RKKY.montecarlo","page":"Home","text":"","title":"MX2RKKY.montecarlo"},{"category":"section","location":"#MX2RKKY.observables","page":"Home","text":"","title":"MX2RKKY.observables"},{"category":"section","location":"#MX2RKKY.utility","page":"Home","text":"","title":"MX2RKKY.utility"},{"category":"section","location":"#MX2RKKY.visualization","page":"Home","text":"","title":"MX2RKKY.visualization"},{"category":"module","location":"#MX2RKKY.MX2RKKY","page":"Home","text":"Monte-Carlo simulation of RKKY-induced chirality of two-dimensional antiferromagnet\n\n\n\n\n\n","title":"MX2RKKY.MX2RKKY"},{"category":"module","location":"#MX2RKKY.lattice","page":"Home","text":"Geometry and graph representation of a triangular lattice cluster\n\n\n\n\n\n","title":"MX2RKKY.lattice"},{"category":"type","location":"#MX2RKKY.lattice.LatCoords","page":"Home","text":"Integer coordinates of 2D lattice vectors in the basis a1 = (1, 0), a2 = (-1/2, √3/2)\n\n\n\n\n\n","title":"MX2RKKY.lattice.LatCoords"},{"category":"method","location":"#MX2RKKY.lattice.LatticeArray-Union{Tuple{D0}, Tuple{T}, Tuple{Function, Type{T}, Integer, Integer, Integer}} where {T, D0}","page":"Home","text":"Make a 2D-dimensional array with axes 0:(L1-1), 0:(L2-1), 0:(L1-1), ... by calling a given function of D LatCoords arguments. The optional argument extra_leading_dims can be used to prepend more axes.\n\n\n\n\n\n","title":"MX2RKKY.lattice.LatticeArray"},{"category":"method","location":"#MX2RKKY.lattice.LatticeArray-Union{Tuple{D0}, Tuple{T}, Tuple{Type{T}, Integer, Integer, Integer}} where {T, D0}","page":"Home","text":"Make a 2D-dimensional zero array with axes 0:(L1-1), 0:(L2-1), 0:(L1-1), ... The optional argument extra_leading_dims can be used to prepend more axes.\n\n\n\n\n\n","title":"MX2RKKY.lattice.LatticeArray"},{"category":"method","location":"#MX2RKKY.lattice.l2p-Tuple{Real, Real}","page":"Home","text":"Convert lattice coordinates on a triangular lattice to physical coordinates\n\n\n\n\n\n","title":"MX2RKKY.lattice.l2p"},{"category":"method","location":"#MX2RKKY.lattice.neighbor_shifts-Tuple{Val{1}}","page":"Home","text":"Return relative integer coordinates of the nearest neighbors on the triangular lattice. The neighbors are listed in the clockwise order.\n\n\n\n\n\n","title":"MX2RKKY.lattice.neighbor_shifts"},{"category":"method","location":"#MX2RKKY.lattice.neighbor_shifts-Tuple{Val{2}}","page":"Home","text":"Return relative integer coordinates of the next-nearest neighbors on the triangular lattice. The neighbors are listed in the clockwise order.\n\n\n\n\n\n","title":"MX2RKKY.lattice.neighbor_shifts"},{"category":"method","location":"#MX2RKKY.lattice.neighbor_shifts-Tuple{Val{3}}","page":"Home","text":"Return relative integer coordinates of the next-next-nearest neighbors on the triangular lattice. The neighbors are listed in the clockwise order.\n\n\n\n\n\n","title":"MX2RKKY.lattice.neighbor_shifts"},{"category":"method","location":"#MX2RKKY.lattice.neighbors-Tuple{CartesianIndex{2}, Int64, Int64}","page":"Home","text":"Given coordinates of a node i, return coordinates of its neighbors on a parallelogram-shaped cluster of the triangular lattice with periodic boundary conditions. The neighbors are listed in the clockwise order. The shape of the cluster is parametrized by two linear sizes, L1 and L2.\n\n\n\n\n\n","title":"MX2RKKY.lattice.neighbors"},{"category":"method","location":"#MX2RKKY.lattice.p2l-Tuple{Real, Real}","page":"Home","text":"Convert physical coordinates to lattice coordinates on a triangular lattice\n\n\n\n\n\n","title":"MX2RKKY.lattice.p2l"},{"category":"method","location":"#MX2RKKY.lattice.periodize-Tuple{CartesianIndex{2}, Int64, Int64}","page":"Home","text":"Given coordinates of a node i, return its coordinates on a parallelogram-shaped cluster of the triangular lattice with periodic boundary conditions. The shape of the cluster is parametrized by two linear sizes, L1 and L2.\n\n\n\n\n\n","title":"MX2RKKY.lattice.periodize"},{"category":"method","location":"#MX2RKKY.lattice.triangle_nodes-Tuple{CartesianIndex{2}, Int64, Int64}","page":"Home","text":"Given coordinates of a node i, return coordinates of the nodes belonging to the same elementary triangle. The nodes belong to a parallelogram-shaped cluster with periodic boundary conditions and are listed in the clockwise order. L1 and L2 are linear sizes of the cluster.\n\n\n\n\n\n","title":"MX2RKKY.lattice.triangle_nodes"},{"category":"module","location":"#MX2RKKY.montecarlo","page":"Home","text":"Implementation of the Monte Carlo sampling\n\n\n\n\n\n","title":"MX2RKKY.montecarlo"},{"category":"method","location":"#Base.IteratorsMD.CartesianIndices-Tuple{MX2RKKY.montecarlo.Configuration}","page":"Home","text":"Iterate over all lattice coordinates of nodes in the cluster from a configuration\n\n\n\n\n\n","title":"Base.IteratorsMD.CartesianIndices"},{"category":"type","location":"#MX2RKKY.montecarlo.Configuration","page":"Home","text":"Configuration as an array of classical spins on a cluster\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.Configuration"},{"category":"method","location":"#MX2RKKY.montecarlo.Configuration-Tuple{Int64, Int64, Int64}","page":"Home","text":"Make a configuration of spins corresponding to the 120° Néel state with a given chirality χ (either -1 or 1). Linear sizes of the configuration L1 and L2 must be multiples of 3.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.Configuration"},{"category":"method","location":"#MX2RKKY.montecarlo.Configuration-Tuple{Int64, Int64, Random.AbstractRNG}","page":"Home","text":"Make a disordered configuration of spins with given linear sizes L1 and L2. Both linear sizes must be multiples of 3. rng is the random number generator used to initialize components of the spins.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.Configuration"},{"category":"type","location":"#MX2RKKY.montecarlo.MCSimulation","page":"Home","text":"State of a Monte Carlo simulation\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.MCSimulation"},{"category":"method","location":"#MX2RKKY.montecarlo.MCSimulation-Tuple{MX2RKKY.montecarlo.Configuration, Random.AbstractRNG}","page":"Home","text":"Construct a simulation structure\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.MCSimulation"},{"category":"type","location":"#MX2RKKY.montecarlo.Measurements","page":"Home","text":"Collection of measurements\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.Measurements"},{"category":"type","location":"#MX2RKKY.montecarlo.MetropolisUpdate","page":"Home","text":"Metropolis update: rotate a given spin by a random angle\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.MetropolisUpdate"},{"category":"method","location":"#Base.getindex-Tuple{MX2RKKY.montecarlo.Configuration, CartesianIndex{2}}","page":"Home","text":"Read orientation of a single spin in a configuration\n\n\n\n\n\n","title":"Base.getindex"},{"category":"method","location":"#Base.setindex!-Tuple{MX2RKKY.montecarlo.Configuration, Float64, CartesianIndex{2}}","page":"Home","text":"Set orientation of a single spin in a configuration\n\n\n\n\n\n","title":"Base.setindex!"},{"category":"method","location":"#Base.size-Tuple{MX2RKKY.montecarlo.Configuration}","page":"Home","text":"Extract linear sizes (L1, L2) of the cluster from a configuration\n\n\n\n\n\n","title":"Base.size"},{"category":"method","location":"#MX2RKKY.montecarlo.Allreduce!-Tuple{MX2RKKY.montecarlo.Measurements, MPI.Comm}","page":"Home","text":"MPI-reduction (summation) of measurement results\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.Allreduce!"},{"category":"method","location":"#MX2RKKY.montecarlo.accept!-Tuple{MX2RKKY.montecarlo.MetropolisUpdate, MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Accept update of a single spin in the cluster\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.accept!"},{"category":"method","location":"#MX2RKKY.montecarlo.chirality-Tuple{MX2RKKY.montecarlo.Configuration, CartesianIndex{2}}","page":"Home","text":"Compute chirality of a single triangle in a given configuration.\n\nThe triangle is specified by the lattice coordinates of its lowest (having the smallest y coordinate) node.\n\nconf - spin configuration. i - lattice coordinates of the node.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.chirality"},{"category":"method","location":"#MX2RKKY.montecarlo.make_rkky_angle_array-Tuple{Int64, Int64}","page":"Home","text":"Make an array of RKKY rotation angles ϕ_{i1,i2}.\n\ni1 and i2 are integer coordinates from the ranges -(L1 - 1)/2:(L1 - 1)/2 and -(L2 - 1)/2:(L2 - 1)/2 respectively.\n\nL1 and L2 - linear sizes of the cluster.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.make_rkky_angle_array"},{"category":"method","location":"#MX2RKKY.montecarlo.make_rkky_int_array-Tuple{Int64, Int64, Float64, Float64}","page":"Home","text":"Make an array of RKKY interactions V_{i1, i2}.\n\ni1 and i2 are integer coordinates from the ranges -(L1 - 1)/2:(L1 - 1)/2 and -(L2 - 1)/2:(L2 - 1)/2 respectively.\n\nL1 and L2 - linear sizes of the cluster. V - RKKY interaction constant V. λ - interaction range parameter k_F a0.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.make_rkky_int_array"},{"category":"method","location":"#MX2RKKY.montecarlo.measure!-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Update measurement data\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.measure!"},{"category":"method","location":"#MX2RKKY.montecarlo.overrelaxation!-Tuple{CartesianIndex{2}, MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Apply the overrelaxation update to a single spin.\n\ni - Lattice coordinates of the updated spin. sim - sim - MC simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.overrelaxation!"},{"category":"method","location":"#MX2RKKY.montecarlo.propose!-Tuple{MX2RKKY.montecarlo.MetropolisUpdate, CartesianIndex{2}, MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Propose update of a single spin in the cluster\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.propose!"},{"category":"method","location":"#MX2RKKY.montecarlo.reset!-Tuple{MX2RKKY.montecarlo.Measurements}","page":"Home","text":"Clear measurement results and pre-allocate sample arrays\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.reset!"},{"category":"method","location":"#MX2RKKY.montecarlo.rkky_angle-Tuple{CartesianIndex{2}}","page":"Home","text":"Compute spin rotation angle of the RKKY interaction ϕ(R).\n\ni - integer coordinates of R.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.rkky_angle"},{"category":"method","location":"#MX2RKKY.montecarlo.rkky_eff_field_contrib-Tuple{MX2RKKY.montecarlo.Configuration, CartesianIndex{2}, Val{0}}","page":"Home","text":"Compute effective field felt by a single node from the RKKY interaction with all other nodes.\n\nconf - configuration of the interacting spins. i - Lattice coordinates of the node. V - RKKY interaction array. ϕ - RKKY rotation angle array.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.rkky_eff_field_contrib"},{"category":"method","location":"#MX2RKKY.montecarlo.rkky_eff_field_contrib-Union{Tuple{R}, Tuple{MX2RKKY.montecarlo.Configuration, CartesianIndex{2}, Val{R}}} where R","page":"Home","text":"Compute effective field felt by a single node from the RKKY interaction with all other nodes within a given range R.\n\nconf - configuration of the interacting spins. i - Lattice coordinates of the node. V - RKKY interaction array. ϕ - RKKY rotation angle array.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.rkky_eff_field_contrib"},{"category":"method","location":"#MX2RKKY.montecarlo.rkky_int-Tuple{CartesianIndex{2}, Float64, Float64}","page":"Home","text":"Compute magnitude of the RKKY interaction V(R).\n\ni - integer coordinates of R. V - RKKY interaction constant V. λ - interaction range parameter k_F a0.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.rkky_int"},{"category":"method","location":"#MX2RKKY.montecarlo.rkky_update_eff_field!-Tuple{OffsetArrays.OffsetArray{Float64, 3, AA} where AA<:AbstractArray{Float64, 3}, MX2RKKY.montecarlo.Configuration, CartesianIndex{2}, Val{0}, Float64}","page":"Home","text":"Recompute contribution of the RKKY interaction with all other nodes to the effective field after a change of a single spin in the cluster.\n\neff_field - effective field. conf - configuration of the interacting spins. i - Lattice coordinates of the updated spin. Δθ - angle change of the spin. V - RKKY interaction array. ϕ - RKKY rotation angle array.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.rkky_update_eff_field!"},{"category":"method","location":"#MX2RKKY.montecarlo.rkky_update_eff_field!-Union{Tuple{R}, Tuple{OffsetArrays.OffsetArray{Float64, 3, AA} where AA<:AbstractArray{Float64, 3}, MX2RKKY.montecarlo.Configuration, CartesianIndex{2}, Val{R}, Float64}} where R","page":"Home","text":"Recompute contribution of the RKKY interaction with all other nodes within a given range R to the effective field after a change of a single spin in the cluster.\n\neff_field - effective field. conf - configuration of the interacting spins. i - Lattice coordinates of the updated spin. Δθ - angle change of the spin. V - RKKY interaction array. ϕ - RKKY rotation angle array.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.rkky_update_eff_field!"},{"category":"method","location":"#MX2RKKY.montecarlo.run!-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Run Monte Carlo simulation.\n\nsim - MC simulation structure. n_mcs - Number of MC steps per spin (MCS). n_warmup_mcs - Number of warm-up MC steps per spin. m_sweeps_per_mcs - Number of Metropolis lattice sweeps per MCS. or_sweeps_per_mcs - Number of overrelaxation lattice sweeps per MCS. maxΔθ - In the Metropolis sweeps, proposed spin rotations belong to the interval           [-maxΔθ, maxΔθ]. show_progress - Show progress meter\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.run!"},{"category":"method","location":"#MX2RKKY.montecarlo.xy_eff_field_contrib-Tuple{MX2RKKY.montecarlo.Configuration, CartesianIndex{2}}","page":"Home","text":"Compute effective field felt by a single node from the Heisenberg XY interaction with its neighbors.\n\nconf - configuration of the interacting spins. i - lattice coordinates of the node. J - Heisenberg interaction constant J.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.xy_eff_field_contrib"},{"category":"method","location":"#MX2RKKY.montecarlo.xy_update_eff_field!-Tuple{OffsetArrays.OffsetArray{Float64, 3, AA} where AA<:AbstractArray{Float64, 3}, MX2RKKY.montecarlo.Configuration, CartesianIndex{2}, Float64}","page":"Home","text":"Recompute contribution of the Heisenberg XY interaction to the effective field after a change of a single spin in the cluster.\n\neff_field - effective field. conf - configuration of the interacting spins. i - lattice coordinates of the updated spin. Δθ - angle change of the spin. J - Heisenberg interaction constant J.\n\n\n\n\n\n","title":"MX2RKKY.montecarlo.xy_update_eff_field!"},{"category":"module","location":"#MX2RKKY.observables","page":"Home","text":"Extraction of physical observables from Monte Carlo sampling results\n\n\n\n\n\n","title":"MX2RKKY.observables"},{"category":"method","location":"#MX2RKKY.observables.avg_chirality-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract average chirality from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.avg_chirality"},{"category":"method","location":"#MX2RKKY.observables.avg_dir_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract average direction of the K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.avg_dir_spin_K"},{"category":"method","location":"#MX2RKKY.observables.avg_energy-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract average energy of the system from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.avg_energy"},{"category":"method","location":"#MX2RKKY.observables.avg_norm_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract average norm of the K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.avg_norm_spin_K"},{"category":"method","location":"#MX2RKKY.observables.avg_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract average K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.avg_spin_K"},{"category":"method","location":"#MX2RKKY.observables.binder_chirality-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract Binder cumulant of chirality from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.binder_chirality"},{"category":"method","location":"#MX2RKKY.observables.binder_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract K-point spin Binder cumulant from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.binder_spin_K"},{"category":"method","location":"#MX2RKKY.observables.corr_chirality_norm_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract correlation between the chirality and the norm of the K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.corr_chirality_norm_spin_K"},{"category":"method","location":"#MX2RKKY.observables.corr_chirality_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract correlation between the chirality and the K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.corr_chirality_spin_K"},{"category":"method","location":"#MX2RKKY.observables.corr_length_chirality-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract correlation length of chirality from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.corr_length_chirality"},{"category":"method","location":"#MX2RKKY.observables.corr_length_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract correlation length of K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.corr_length_spin_K"},{"category":"method","location":"#MX2RKKY.observables.cov_chirality_long_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract covariance between the chirality and the longitudinal component of the K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.cov_chirality_long_spin_K"},{"category":"method","location":"#MX2RKKY.observables.cov_chirality_norm_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract covariance between the chirality and the norm of the K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.cov_chirality_norm_spin_K"},{"category":"method","location":"#MX2RKKY.observables.cov_chirality_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract covariance between the chirality and the K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.cov_chirality_spin_K"},{"category":"method","location":"#MX2RKKY.observables.cov_chirality_trans_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract covariance between the chirality and the transversal component of the K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.cov_chirality_trans_spin_K"},{"category":"method","location":"#MX2RKKY.observables.err_chirality-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract estimated Monte Carlo error of the average chirality from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.err_chirality"},{"category":"method","location":"#MX2RKKY.observables.err_energy-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract estimated Monte Carlo error of the average energy of the system from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.err_energy"},{"category":"method","location":"#MX2RKKY.observables.err_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract estimated Monte Carlo error of the average K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.err_spin_K"},{"category":"method","location":"#MX2RKKY.observables.min_energy-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract the lowest encountered energy from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.min_energy"},{"category":"method","location":"#MX2RKKY.observables.specific_heat-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract specific heat of the system from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.specific_heat"},{"category":"method","location":"#MX2RKKY.observables.susc_chirality-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract chiral susceptibility from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.susc_chirality"},{"category":"method","location":"#MX2RKKY.observables.susc_norm_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract K-point spin norm susceptibility from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.susc_norm_spin_K"},{"category":"method","location":"#MX2RKKY.observables.susc_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract K-point spin susceptibility from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.susc_spin_K"},{"category":"method","location":"#MX2RKKY.observables.var_chirality-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract variance of chirality from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.var_chirality"},{"category":"method","location":"#MX2RKKY.observables.var_energy-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract variance of energy from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.var_energy"},{"category":"method","location":"#MX2RKKY.observables.var_norm_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract variance of the norm of the K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.var_norm_spin_K"},{"category":"method","location":"#MX2RKKY.observables.var_spin_K-Tuple{MX2RKKY.montecarlo.MCSimulation}","page":"Home","text":"Extract variance of K-point magnetization from a simulation structure.\n\n\n\n\n\n","title":"MX2RKKY.observables.var_spin_K"},{"category":"module","location":"#MX2RKKY.utility","page":"Home","text":"Utility functions\n\n\n\n\n\n","title":"MX2RKKY.utility"},{"category":"method","location":"#MX2RKKY.utility.clamp_angle-Tuple{Float64}","page":"Home","text":"Cast a given angle ϕ into the range [-π; π]\n\n\n\n\n\n","title":"MX2RKKY.utility.clamp_angle"},{"category":"function","location":"#MX2RKKY.utility.range_of_nonmissing","page":"Home","text":"Iterate along the last axis of a given array and discard all slices containing at least one missing value. Then take a range over the last axis. By default, all non-missing elements are taken.\n\n\n\n\n\n","title":"MX2RKKY.utility.range_of_nonmissing"},{"category":"module","location":"#MX2RKKY.visualization","page":"Home","text":"Visualization (plotting) functions\n\n\n\n\n\n","title":"MX2RKKY.visualization"},{"category":"method","location":"#MX2RKKY.visualization.plot_conf-Tuple{MX2RKKY.montecarlo.Configuration}","page":"Home","text":"Visualize a spin configuration and chirality of hexagonal cells\n\n\n\n\n\n","title":"MX2RKKY.visualization.plot_conf"}]
}
